package app.awesom.root

import android.content.Context
import org.json.JSONObject
import java.io.File

/**
 * The canonical index the app reads: [Loader] + [Target] entries generated by
 * `tools/build_index.py` from the 122 cloned upstream repos.
 *
 * Only `klass == "kernel-lpe"` (or `multi-method`) loaders are offered as runnable;
 * everything else is shown for reference and never executed.
 */
data class Loader(
    val id: String,
    val name: String,
    val cve: String,
    val klass: String,
    val repo: String,
    val upstream: String,
    val transport: String,
    val runner: String,
    val kmiFrom: String,
    val status: String,
) {
    val runnable: Boolean get() = klass == "kernel-lpe" || klass == "multi-method"
    val needsPc: Boolean get() = klass == "boot-chain" || klass == "research" || klass == "tool"
}

data class Target(
    val loader: String,
    val matchKind: String,
    val matchKey: String,
    val kernel: String?,
    val kmi: String?,
    val devices: List<String>,
    val page: String?,
    val runner: String?,
    val note: String?,
    val source: String?,
    val extra: JSONObject?,
) {
    /** Confidence that this target is the one the running device wants. */
    fun score(p: DeviceProfile): Int {
        var s = 0
        val key = p.matchKey
        val k = kernel
        if (k != null) {
            if (k == key) s += 100
            else if (key.startsWith(k) || k.startsWith(key)) s += 20
            else return -1
        }
        val model = p.model
        val dev = p.device
        val devs = devices.filter { it.isNotBlank() }
        if (devs.isNotEmpty()) {
            val hit = devs.any {
                it.equals(model, true) || it.equals(dev, true) ||
                    model.startsWith(it, true) || dev.startsWith(it, true) ||
                    it.contains(dev, true) || dev.contains(it, true)
            }
            if (hit) s += 40 else s -= 30
        }
        val pg = page
        if (pg != null) {
            if (pg.trim() == p.pageSize.toString()) s += 30 else s -= 100
        }
        if (kmi != null && kmi.isNotBlank()) {
            val want = kmiFor(p.kernelRelease)
            if (want != null && want == kmi) s += 25 else s -= 25
        }
        return s
    }
}

object IndexStore {

    private var loaders: List<Loader> = emptyList()
    private var targets: List<Target> = emptyList()

    fun load(context: Context): Boolean {
        val text = runCatching {
            context.assets.open("loaders.json").bufferedReader().use { it.readText() }
        }.getOrNull() ?: return false
        return parse(text)
    }

    fun parse(text: String): Boolean = runCatching {
        val root = JSONObject(text)
        val ls = mutableListOf<Loader>()
        val arr = root.optJSONArray("loaders") ?: return false
        for (i in 0 until arr.length()) {
            val o = arr.getJSONObject(i)
            ls += Loader(
                id = o.optString("id"),
                name = o.optString("name"),
                cve = o.optString("cve"),
                klass = o.optString("klass"),
                repo = o.optString("repo"),
                upstream = o.optString("upstream"),
                transport = o.optString("transport"),
                runner = o.optString("runner"),
                kmiFrom = o.optString("kmi_from"),
                status = o.optString("status"),
            )
        }
        val ts = mutableListOf<Target>()
        val tarr = root.optJSONArray("targets") ?: return false
        for (i in 0 until tarr.length()) {
            val o = tarr.getJSONObject(i)
            val devs = mutableListOf<String>()
            val da = o.optJSONArray("devices")
            if (da != null) for (j in 0 until da.length()) devs += da.optString(j)
            ts += Target(
                loader = o.optString("loader"),
                matchKind = o.optString("match_kind"),
                matchKey = o.optString("match_key"),
                kernel = o.optString("kernel").ifBlank { null },
                kmi = o.optString("kmi").ifBlank { null },
                devices = devs,
                page = o.optString("page").ifBlank { null },
                runner = o.optString("runner").ifBlank { null },
                note = o.optString("note").ifBlank { null },
                source = o.optString("source").ifBlank { null },
                extra = o.optJSONObject("extra"),
            )
        }
        loaders = ls
        targets = ts
        true
    }.getOrDefault(false)

    fun loaders(): List<Loader> = loaders
    fun targets(): List<Target> = targets

    fun loader(id: String): Loader? = loaders.firstOrNull { it.id == id }

    /** Ranked candidates for the running device; best first, negatives dropped. */
    fun candidates(p: DeviceProfile, runnableOnly: Boolean = true): List<Pair<Loader, Target>> {
        val out = mutableListOf<Triple<Loader, Target, Int>>()
        for (t in targets) {
            val l = loader(t.loader) ?: continue
            if (runnableOnly && !l.runnable) continue
            val s = t.score(p)
            if (s > 0) out += Triple(l, t, s)
        }
        return out.sortedByDescending { it.third }.map { it.first to it.second }
    }

    /**
     * Derives the Kernel Module Interface (`android15-6.6`) from a full
     * `uname -r`, which is what every loader's `ksud late-load --kmi` needs.
     */
    fun kmiFor(release: String): String? {
        if (release.isBlank()) return null
        val m = Regex("""^(\d+\.\d+(?:\.\d+)?)-android(\d+)-(\d+)""").find(release) ?: return null
        val (kernel, android, gki) = m.destructured
        return "android$android-$kernel"
    }

    /** Writes the current index back out (used by the debug screen). */
    fun dumpTo(context: Context): File {
        val f = File(context.filesDir, "loaders-dump.json")
        f.writeText("{\"loaders\":${loaders.size},\"targets\":${targets.size}}")
        return f
    }
}
